/**
 * Writers for FLAC fixtures, native and in Ogg, generated by code. Frames use
 * verbatim subframes, the simplest valid encoding, with correct CRC-8,
 * CRC-16 and Ogg CRC-32, so browsers can decode them too. Options produce
 * the crafted headers the walkers must refuse.
 */
import { crc8, crc16Step, crc32 } from "../../src/adapters/bytes/crc.js";

export interface FlacOptions {
  readonly sampleRate?: number;
  readonly bits?: 8 | 16 | 24;
  /** Frames per FLAC frame; the last may be shorter. */
  readonly blockSize?: number;
  /** STREAMINFO's total, instead of the real one. 0 means unknown. */
  readonly totalFrames?: number;
  /** A sample rate code written in every frame header, instead of "as in STREAMINFO". */
  readonly frameRateCode?: number;
  /** A channel count written in STREAMINFO, instead of the real one. */
  readonly streamInfoChannels?: number;
  /** An ID3v2 tag before the fLaC marker. */
  readonly id3?: boolean;
}

const SIZE_CODES = { 8: 1, 16: 4, 24: 6 } as const;

function utf8Number(value: number): number[] {
  if (value < 0x80) return [value];
  if (value < 0x800) return [0xc0 | (value >> 6), 0x80 | (value & 0x3f)];
  return [0xe0 | (value >> 12), 0x80 | ((value >> 6) & 0x3f), 0x80 | (value & 0x3f)];
}

/** One FLAC frame with verbatim subframes. */
export function flacFrame(
  channels: readonly (readonly number[])[],
  start: number,
  length: number,
  index: number,
  options: FlacOptions = {},
): number[] {
  const bits = options.bits ?? 16;
  const header = [
    0xff,
    0xf8,
    (7 << 4) | (options.frameRateCode ?? 0),
    ((channels.length - 1) << 4) | (SIZE_CODES[bits] << 1),
    ...utf8Number(index),
    ((length - 1) >> 8) & 0xff,
    (length - 1) & 0xff,
  ];
  const rateCode = options.frameRateCode ?? 0;
  if (rateCode === 12) header.push(48);
  header.push(crc8(Uint8Array.from(header)));
  const frame = [...header];
  const scale = 2 ** (bits - 1);
  for (const channel of channels) {
    frame.push(0x02); // a verbatim subframe, no wasted bits
    for (let i = start; i < start + length; i += 1) {
      const value = Math.max(-scale, Math.min(scale - 1, Math.round((channel[i] ?? 0) * scale)));
      const unsigned = value < 0 ? value + 2 * scale : value;
      for (let shift = bits - 8; shift >= 0; shift -= 8) frame.push((unsigned >> shift) & 0xff);
    }
  }
  let crc = 0;
  for (const byte of frame) crc = crc16Step(crc, byte);
  frame.push(crc >> 8, crc & 0xff);
  return frame;
}

/** The 34-byte STREAMINFO body. */
export function streamInfo(channels: number, frames: number, options: FlacOptions = {}): number[] {
  const blockSize = options.blockSize ?? 64;
  const rate = options.sampleRate ?? 8_000;
  const bits = options.bits ?? 16;
  const total = options.totalFrames ?? frames;
  const out = new Uint8Array(34);
  const view = new DataView(out.buffer);
  view.setUint16(0, blockSize);
  view.setUint16(2, blockSize);
  const channelCount = options.streamInfoChannels ?? channels;
  view.setUint32(
    10,
    ((rate << 12) | ((channelCount - 1) << 9) | ((bits - 1) << 4) | Math.floor(total / 2 ** 32)) >>>
      0,
  );
  view.setUint32(14, total % 2 ** 32);
  return [...out];
}

/** The audio frames of a stream, as separate byte arrays. */
export function flacFrames(
  channels: readonly (readonly number[])[],
  options: FlacOptions = {},
): number[][] {
  const blockSize = options.blockSize ?? 64;
  const total = channels[0]?.length ?? 0;
  const frames: number[][] = [];
  for (let start = 0, index = 0; start < total; start += blockSize, index += 1) {
    frames.push(flacFrame(channels, start, Math.min(blockSize, total - start), index, options));
  }
  return frames;
}

/** A native FLAC file holding these samples, one array per channel. */
export function flacFile(
  channels: readonly (readonly number[])[],
  options: FlacOptions = {},
): Uint8Array<ArrayBuffer> {
  const frames = channels[0]?.length ?? 0;
  const id3 = options.id3 ? [0x49, 0x44, 0x33, 4, 0, 0, 0, 0, 0, 10, ...new Array(10).fill(0)] : [];
  const bytes = [
    ...id3,
    ...[0x66, 0x4c, 0x61, 0x43], // fLaC
    0x00,
    0,
    0,
    34, // STREAMINFO, not last
    ...streamInfo(channels.length, frames, options),
    0x84,
    0,
    0,
    8, // VORBIS_COMMENT, last
    0,
    0,
    0,
    0,
    0,
    0,
    0,
    0, // an empty vendor string and no comments
    ...flacFrames(channels, options).flat(),
  ];
  return Uint8Array.from(bytes);
}

export interface OggOptions extends FlacOptions {
  /** The last page's granule position, instead of the real total. */
  readonly lastGranule?: number;
  /** A second logical stream begins on the second page. */
  readonly multiplexed?: boolean;
}

/** One Ogg page carrying whole packets. */
export function oggPage(
  packets: readonly number[][],
  options: { serial: number; sequence: number; granule: number; type: number },
): number[] {
  const lacing: number[] = [];
  for (const packet of packets) {
    let length = packet.length;
    while (length >= 255) {
      lacing.push(255);
      length -= 255;
    }
    lacing.push(length);
  }
  const header = new Uint8Array(27 + lacing.length);
  const view = new DataView(header.buffer);
  header.set([0x4f, 0x67, 0x67, 0x53], 0);
  view.setUint8(5, options.type);
  if (options.granule < 0) {
    view.setUint32(6, 0xffffffff, true);
    view.setUint32(10, 0xffffffff, true);
  } else {
    view.setUint32(6, options.granule % 2 ** 32, true);
    view.setUint32(10, Math.floor(options.granule / 2 ** 32), true);
  }
  view.setUint32(14, options.serial, true);
  view.setUint32(18, options.sequence, true);
  view.setUint8(26, lacing.length);
  header.set(lacing, 27);
  const page = Uint8Array.from([...header, ...packets.flat()]);
  new DataView(page.buffer).setUint32(22, crc32(page), true);
  return [...page];
}

/** FLAC in Ogg holding these samples: one frame per page. */
export function oggFlacFile(
  channels: readonly (readonly number[])[],
  options: OggOptions = {},
): Uint8Array<ArrayBuffer> {
  const total = channels[0]?.length ?? 0;
  const blockSize = options.blockSize ?? 64;
  const mapping = [
    0x7f,
    0x46,
    0x4c,
    0x41,
    0x43,
    1,
    0,
    0,
    1, // "\x7FFLAC", version 1.0, one header packet
    0x66,
    0x4c,
    0x61,
    0x43, // fLaC
    0x00,
    0,
    0,
    34,
    ...streamInfo(channels.length, total, options),
  ];
  const comment = [0x84, 0, 0, 8, 0, 0, 0, 0, 0, 0, 0, 0];
  const serial = 0x1234;
  const pages = [oggPage([mapping], { serial, sequence: 0, granule: 0, type: 0x02 })];
  if (options.multiplexed) {
    pages.push(oggPage([[1, 2, 3]], { serial: 0x9999, sequence: 0, granule: 0, type: 0x02 }));
  }
  pages.push(oggPage([comment], { serial, sequence: 1, granule: 0, type: 0 }));
  const frames = flacFrames(channels, options);
  for (const [index, frame] of frames.entries()) {
    const last = index === frames.length - 1;
    const granule =
      last && options.lastGranule !== undefined
        ? options.lastGranule
        : Math.min(total, (index + 1) * blockSize);
    pages.push(oggPage([frame], { serial, sequence: index + 2, granule, type: last ? 0x04 : 0 }));
  }
  return Uint8Array.from(pages.flat());
}
